import { useState, useEffect, useRef } from 'react'
import { useConnectModal } from '@rainbow-me/rainbowkit'
import { useWriteContract, useAccount, useWaitForTransactionReceipt, useBalance, usePublicClient } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { parseUnits, formatUnits, isAddress } from 'viem'
import { VAULT_ABI } from './abi.js'
import { getVaultAddress } from './config.js'
import { encodeTicket, saveTicket, updateTicketStatus, updateTicketTxHash } from './ticketUtils.js'
import { getChainInfo, getTxUrl, fmtDisplay } from './chainUtils.js'
import { useTxHistory } from './useTxHistory.js'
import PctBtns from './PctBtns.jsx'
import { getTokens, defaultPresets, NATIVE } from './tokenList.js'

const ERC20_ABI = [
  { type:'function', name:'allowance',  inputs:[{type:'address'},{type:'address'}], outputs:[{type:'uint256'}], stateMutability:'view' },
  { type:'function', name:'approve',    inputs:[{type:'address'},{type:'uint256'}], outputs:[{type:'bool'}],    stateMutability:'nonpayable' },
  { type:'function', name:'symbol',     inputs:[], outputs:[{type:'string'}],  stateMutability:'view' },
  { type:'function', name:'decimals',   inputs:[], outputs:[{type:'uint8'}],   stateMutability:'view' },
]

function sanitizeAmount(v) {
  return v.replace(/[^0-9.]/g, '').replace(/^(\d*\.?\d*).*$/, '$1')
}

export default function Deposit() {
  const { address } = useAccount()
  const { openConnectModal } = useConnectModal()
  const { activeChainId: chainId } = useGuestChain()
  const { addTx } = useTxHistory()
  const publicClient = usePublicClient()
  const pollRef = useRef(null)
  const VAULT_ADDRESS = getVaultAddress(chainId)

  const presetTokens = getTokens(chainId)
  const [token, setToken] = useState(presetTokens[0])
  useEffect(() => { setToken(getTokens(chainId)[0]) }, [chainId])
  const [customAddr, setCustomAddr] = useState('')
  const [customErr, setCustomErr] = useState('')
  const [showCustom, setShowCustom] = useState(false)

  const [amount, setAmount] = useState('')
  const [isZkReady, setIsZkReady] = useState(false)
  useEffect(() => { window.__zkReady.then(() => setIsZkReady(true)) }, [])
  const [ticket, setTicket] = useState(null)
  const [confirmed, setConfirmed] = useState(false)
  const [txHash, setTxHash] = useState(null)
  const [status, setStatus] = useState('')
  const [copied, setCopied] = useState(false)
  const [approveStep, setApproveStep] = useState('idle') // idle | approving | approved
  const { writeContractAsync, isPending } = useWriteContract()
  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({ hash: txHash })

  const isNative = token.address === NATIVE
  const { data: walletBalance, refetch: refetchBalance } = useBalance({
    address,
    token: isNative ? undefined : token.address,
    chainId,
    query: { enabled: !!address },
  })
  useEffect(() => { if (isSuccess) refetchBalance() }, [isSuccess]) // eslint-disable-line

  const PRESETS = defaultPresets(token)
  const amountNum = parseFloat(amount)
  const balanceNum = walletBalance ? parseFloat(formatUnits(walletBalance.value, token.decimals)) : null
  const amountErr = amount && (isNaN(amountNum) || amountNum <= 0)
    ? 'Amount must be > 0'
    : amount && balanceNum !== null && amountNum > balanceNum
    ? `Insufficient balance (max ${fmtDisplay(walletBalance.value, token.decimals)} ${token.symbol})`
    : ''



  // resolve custom token address
  async function resolveCustom(addr) {
    setCustomErr('')
    if (!addr) return
    if (!isAddress(addr)) { setCustomErr('Invalid address'); return }
    try {
      const [sym, dec] = await Promise.all([
        publicClient.readContract({ address: addr, abi: ERC20_ABI, functionName: 'symbol' }),
        publicClient.readContract({ address: addr, abi: ERC20_ABI, functionName: 'decimals' }),
      ])
      setToken({ symbol: sym, address: addr.toLowerCase(), decimals: Number(dec) })
      setCustomErr('')
    } catch {
      setCustomErr('Could not read token — check address')
    }
  }

  function selectPreset(t) {
    setToken(t)
    setShowCustom(false)
    setCustomAddr('')
    setCustomErr('')
    setTicket(null)
    setApproveStep('idle')
  }

  function doDownload(note, amt, sym) {
    const text = encodeTicket(note)
    const url = URL.createObjectURL(new Blob([text], { type: 'text/plain' }))
    Object.assign(document.createElement('a'), { href: url, download: `cloakcash-ticket-${amt}${sym}.txt` }).click()
    URL.revokeObjectURL(url)
  }

  async function handleGenerate() {
    if (!amount || !address || amountErr) return
    const n = await window.__zk.generateTicket(token.address, amount, chainId, token.decimals ?? 18)
    saveTicket(n)
    setTicket(n)
    doDownload(n, amount, token.symbol)
    setConfirmed(false)
    setTxHash(null)
    setStatus('')
    setApproveStep('idle')
  }

  function downloadTicket() { doDownload(ticket, amount, token.symbol) }

  const ticketRef = useRef(null)
  useEffect(() => { if (ticket) ticketRef.current = ticket }, [ticket])

  useEffect(() => {
    if (!txHash || !publicClient) return
    if (isSuccess) { if (ticketRef.current) updateTicketStatus(ticketRef.current.commitment, 'deposited'); return }
    pollRef.current = setInterval(async () => {
      try {
        const receipt = await publicClient.getTransactionReceipt({ hash: txHash })
        if (receipt?.status === 'success') { if (ticketRef.current) updateTicketStatus(ticketRef.current.commitment, 'deposited'); clearInterval(pollRef.current) }
      } catch {}
    }, 4000)
    return () => clearInterval(pollRef.current)
  }, [txHash, isSuccess]) // eslint-disable-line

  async function handleDeposit() {
    try {
      setStatus('')
      const amtWei = parseUnits(amount, token.decimals)

      // ERC-20: check allowance, approve if needed
      if (!isNative && approveStep !== 'approved') {
        const allowance = await publicClient.readContract({
          address: token.address, abi: ERC20_ABI, functionName: 'allowance',
          args: [address, VAULT_ADDRESS],
        })
        if (allowance < amtWei) {
          setApproveStep('approving')
          setStatus('Approving token…')
          const appHash = await writeContractAsync({
            address: token.address, abi: ERC20_ABI, functionName: 'approve',
            args: [VAULT_ADDRESS, amtWei],
          })
          // wait for approve confirmation
          await publicClient.waitForTransactionReceipt({ hash: appHash })
          setApproveStep('approved')
          setStatus('')
        } else {
          setApproveStep('approved')
        }
      }

      // fetch fresh nonce after approve (or if already approved) to avoid nonce collision
      const nonce = await publicClient.getTransactionCount({ address, blockTag: 'pending' })
      const hash = await writeContractAsync({
        address: VAULT_ADDRESS,
        abi: VAULT_ABI,
        functionName: 'deposit',
        args: [token.address, amtWei, ticket.commitment],
        value: isNative ? amtWei : 0n,
        nonce,
      })
      setTxHash(hash)
      updateTicketTxHash(ticket.commitment, hash)
      addTx({ hash, type: 'Private Deposit', amount, currency: token.symbol, chainId, status: 'pending' })
      setApproveStep('idle')
    } catch (e) {
      setApproveStep('idle')
      setStatus('❌ ' + (e.shortMessage || e.message))
    }
  }

  const txUrl = txHash ? getTxUrl(chainId, txHash) : null
  const canGenerate = !!amount && !amountErr && isZkReady

  return (
    <div className="card">
      <h2>Private Deposit</h2>
      <p className="sub">Deposit into Uniswap v4 PoolManager privacy vault. Save your ticket to withdraw later.</p>

      {/* Token picker */}
      <div className="token-picker">
        {presetTokens.map(t => (
          <button key={t.address} className={`token-btn ${token.address === t.address ? 'active' : ''}`}
            onClick={() => selectPreset(t)}>
            {t.symbol}
          </button>
        ))}
        <button className={`token-btn ${showCustom ? 'active' : ''}`}
          onClick={() => { setShowCustom(s => !s) }}>
          + Custom
        </button>
      </div>

      {showCustom && (
        <div style={{marginBottom:'12px'}}>
          <div className="token-custom-wrap">
            <input
              className={`token-custom-input ${customErr ? 'err' : ''}`}
              placeholder="Token contract address (0x…)"
              value={customAddr}
              onChange={e => setCustomAddr(e.target.value)}
              onBlur={() => resolveCustom(customAddr)}
            />
            <button className="btn-copy" onClick={() => resolveCustom(customAddr)}>Load</button>
          </div>
          {customErr && <div className="token-custom-label" style={{color:'#f43f5e'}}>{customErr}</div>}
          {!customErr && token.address === customAddr?.toLowerCase() && customAddr && (
            <div className="token-custom-label">✓ {token.symbol} · {token.decimals} decimals</div>
          )}
        </div>
      )}

      {/* Amount presets */}
      <div className="presets">
        {PRESETS.map(p => (
          <button key={p} className={`preset ${amount === p ? 'active' : ''}`}
            onClick={() => { setAmount(p); setTicket(null) }}>
            {p} {token.symbol}
          </button>
        ))}
      </div>

      <div className={`input-panel ${amountErr ? 'input-err' : ''}`}>
        <div className="input-panel-label">Amount</div>
        <div className="input-panel-row">
          <input className="input-big" type="text" inputMode="decimal" placeholder="0"
            value={amount}
            onChange={e => { setAmount(sanitizeAmount(e.target.value)); setTicket(null) }} />
          <div className="input-currency">
            <span className="token-sym-dot" />{token.symbol}
          </div>
        </div>
        <div className="input-balance">
          <span>{walletBalance ? `Balance: ${fmtDisplay(walletBalance.value, token.decimals)} ${token.symbol}` : ''}</span>
        </div>
        {walletBalance && <PctBtns balance={walletBalance.value} decimals={token.decimals} isNative={isNative} amount={amount} setAmount={v => { setAmount(v); setTicket(null) }} />}
      </div>
      {amountErr && <div className="status err">{amountErr}</div>}

      {!ticket && (
        <button className="btn-primary"
          onClick={!address ? (openConnectModal ?? (() => document.querySelector('.uc-connect-btn')?.click())) : handleGenerate}
          disabled={!!address && !canGenerate}>
          {!address ? 'Connect' : !isZkReady ? <><span className="spinner" /> Loading ZK…</> : 'Generate Ticket'}
        </button>
      )}

      {ticket && !isSuccess && (
        <div className="ticket-box">
          <div className="ticket-label">Step 1 — Save your ticket before depositing</div>
          <div className="ticket-text">{encodeTicket(ticket)}</div>
          <div style={{display:'flex',gap:'8px'}}>
            <button className="btn-copy" style={{flex:1}} onClick={downloadTicket}>⬇ Download</button>
            <button className="btn-copy" style={{flex:1}} onClick={() => { navigator.clipboard.writeText(encodeTicket(ticket)); setCopied(true); setTimeout(() => setCopied(false), 2000) }}>{copied ? '✓ Copied' : 'Copy'}</button>
          </div>
          <label style={{display:'flex',alignItems:'center',gap:'10px',cursor:'pointer',fontSize:'13px',color:'var(--text2)'}}>
            <input type="checkbox" checked={confirmed} onChange={e => setConfirmed(e.target.checked)} style={{width:'16px',height:'16px',accentColor:'var(--a1)',flexShrink:0}} />
            I've saved my ticket. Losing it means losing my funds.
          </label>
          <div className="ticket-warn">⚠ Not stored on-chain or on any server — only you have it. Keep it safe.</div>
          <button className="btn-primary" onClick={handleDeposit}
            disabled={!confirmed || isPending || isConfirming || approveStep === 'approving'}>
            {approveStep === 'approving'
              ? <><span className="spinner" />Approving {token.symbol}…</>
              : isPending ? <><span className="spinner" />Confirm in wallet…</>
              : isConfirming ? <><span className="spinner" />Confirming…</>
              : `Step 2 — Deposit ${amount} ${token.symbol}`}
          </button>
          {status && <div className={`status ${status.startsWith('❌') ? 'err' : 'info'}`}>{status}</div>}
          {txHash && !isSuccess && (
            <div className="status info">Tx submitted… {txUrl && <a href={txUrl} target="_blank" rel="noreferrer">View ↗</a>}</div>
          )}
          <button className="btn-copy" onClick={() => { setTicket(null); setAmount(''); setApproveStep('idle') }}>← Change amount</button>
        </div>
      )}

      {isSuccess && (
        <div className="ticket-box">
          <div className="ticket-label">Deposit confirmed ✓</div>
          <div className="ticket-text">{encodeTicket(ticket)}</div>
          <div className="ticket-warn">⚠ Keep this ticket safe — it's the only way to withdraw.</div>
          <div style={{display:'flex',gap:'8px'}}>
            {txUrl && <a className="btn-copy" href={txUrl} target="_blank" rel="noreferrer" style={{textDecoration:'none',textAlign:'center',flex:1}}>View tx ↗</a>}
            <button className="btn-copy" style={{flex:1}} onClick={() => { setTicket(null); setTxHash(null); setAmount(''); setApproveStep('idle') }}>New Deposit</button>
          </div>
        </div>
      )}
    </div>
  )
}
